DEFAULT_QC_INPUT_DIR = "/store_new/mch/msrad/radar/radar_database_v2/rf_input_data_qc/"


def load_qc_dataset(input_dir, radar_columns=None):
    """Load the QC radar dataset and related metadata."""
    radar_path = os.path.join(input_dir, "radar_x0y0.parquet")
    gauge_path = os.path.join(input_dir, "gauge.parquet")
    grouping_path = os.path.join(input_dir, "grouping_idx_x0y0.p")

    if radar_columns is None:
        radar_columns = [
            "RADAR",
            "HEIGHT",
            "ISO0_HEIGHT",
            "ZH_mean",
            "ZV_mean",
            "KDP_mean",
            "RHOHV_mean",
            "SW_mean",
            "AH_mean",
            "VISIB_mean",
            "SWEEP",
        ]

    radar = pd.read_parquet(radar_path, columns=radar_columns)
    gauge = pd.read_parquet(gauge_path)

    with open(grouping_path, "rb") as f:
        grouping = pickle.load(f)

    if "grp_vertical" not in grouping:
        raise KeyError("Expected grouping index key 'grp_vertical' in grouping_idx_x0y0.p")

    vertgroups = np.asarray(grouping["grp_vertical"])
    return radar, gauge, vertgroups


def save_figure(fig, output_dir, filename):
    os.makedirs(output_dir, exist_ok=True)
    path = os.path.join(output_dir, filename)
    fig.tight_layout()
    fig.savefig(path, dpi=200)
    plt.close(fig)
    print(f"Saved: {path}")


def plot_gauge_distribution(gauge, output_dir):
    fig, ax = plt.subplots(figsize=(10, 5))
    
    target_data = gauge["RRE150Z0"].dropna()
    sns.histplot(target_data.clip(lower=1e-3), bins=80, ax=ax, color="#548235")
    ax.set_yscale("log")
    ax.set_title("Gauge Target Distribution")
    ax.set_xlabel("Precipitation (mm/10min)")
    ax.set_ylabel("Count")
    
    stats_text = (
        f"Count : {len(target_data):,}\n"
        f"Min   : {target_data.min():.2f}\n"
        f"Max   : {target_data.max():.2f}\n"
        f"Mean  : {target_data.mean():.4f}\n"
        f"Std   : {target_data.std():.4f}\n"
        f"25%   : {target_data.quantile(0.25):.2f}\n"
        f"50%   : {target_data.quantile(0.50):.2f}\n"
        f"75%   : {target_data.quantile(0.75):.2f}\n"
        f"90%   : {target_data.quantile(0.90):.2f}\n"
        f"95%   : {target_data.quantile(0.95):.2f}\n"
        f"99%   : {target_data.quantile(0.99):.2f}\n"
        f"99.9% : {target_data.quantile(0.999):.2f}"
    )
    
    props = dict(boxstyle='round,pad=0.5', facecolor='white', alpha=0.8, edgecolor='gray')
    ax.text(0.95, 0.95, stats_text, transform=ax.transAxes, fontsize=10,
            verticalalignment='top', horizontalalignment='right', 
            bbox=props, family='monospace') # Using monospace helps align the numbers nicely
    save_figure(fig, output_dir, "gauge_distribution_log.png")


def plot_gauge_timeline(gauge, output_dir):
    if "TIMESTAMP" not in gauge.columns:
        raise KeyError("Gauge table must contain a TIMESTAMP column for timeline plotting.")

    gauge = gauge.copy()
    # print(gauge["TIMESTAMP"].describe())
    gauge["TIMESTAMP"] = pd.to_datetime(gauge['TIMESTAMP'], unit="s")
    gauge = gauge.sort_values("TIMESTAMP")

    fig, ax = plt.subplots(figsize=(14, 6))
    ax.plot(gauge["TIMESTAMP"], gauge["RRE150Z0"], marker=".", linestyle="None", markersize=2, alpha=0.4)
    ax.set_title("Gauge Precipitation Timeline")
    ax.set_xlabel("Month-Year")
    ax.set_ylabel("Precipitation (mm/10min)")
    # ax.xaxis.set_major_locator(mdates.MonthLocator(interval=1))
    # ax.xaxis.set_major_formatter(mdates.DateFormatter("%Y-%m"))
    ax.xaxis.set_major_formatter(mdates.DateFormatter('%b-%Y'))
    ax.grid(True, alpha=0.3)
    fig.autofmt_xdate()
    save_figure(fig, output_dir, "gauge_precip_timeline_month_year.png")
    


def plot_radar_category_distribution(radar, output_dir):
    fig, ax = plt.subplots(figsize=(10, 5))
    order = radar["RADAR"].value_counts().index
    sns.countplot(data=radar, x="RADAR", order=order, palette="crest", ax=ax)
    ax.set_title("RADAR Category Counts")
    ax.set_ylabel("Count")
    ax.set_xlabel("RADAR")
    ax.set_xticklabels(ax.get_xticklabels(), rotation=45, ha="right")
    save_figure(fig, output_dir, "radar_category_counts.png")


def plot_height_distribution(radar, output_dir):
    fig, ax = plt.subplots(figsize=(10, 5))
    sns.histplot(radar["HEIGHT"], bins=40, ax=ax, alpha=1)
    ax.set_title("Radar HEIGHT Distribution")
    ax.set_xlabel("HEIGHT")
    ax.set_ylabel("Count")
    ax.set_yscale("log")
    save_figure(fig, output_dir, "height_distribution.png")


def plot_sequence_length_distribution(vertgroups, output_dir):
    group_counts = pd.Series(vertgroups).value_counts().sort_index()
    fig, ax = plt.subplots(figsize=(10, 5))
    sns.histplot(group_counts, bins=30, ax=ax, log_scale=[False, True], alpha=1)
    ax.set_title("Vertical Profile Length Distribution")
    ax.set_xlabel("Number of radar rows per vertgroup")
    ax.set_ylabel("Number of groups")
    ax.set_yscale("log")
    save_figure(fig, output_dir, "sequence_length_distribution.png")

    stats = group_counts.describe()
    print("Sequence length summary:")
    print(stats)


def aggregate_by_group(radar, gauge, vertgroups):
    grouped = radar.copy()
    grouped["vertgroup"] = vertgroups
    summary = grouped.groupby("vertgroup").agg(
        HEIGHT_mean=("HEIGHT", "mean"),
        HEIGHT_median=("HEIGHT", "median"),
        HEIGHT_max=("HEIGHT", "max"),
        ZH_mean_mean=("ZH_mean", "mean"),
        ZV_mean_mean=("ZV_mean", "mean"),
        KDP_mean_mean=("KDP_mean", "mean"),
        RHOHV_mean_mean=("RHOHV_mean", "mean"),
        AW_mean=("AH_mean", "mean"),
        VISIB_mean_mean=("VISIB_mean", "mean"),
        SW_mean_mean=("SW_mean", "mean"),
        SWEEP_mode=("SWEEP", lambda x: x.mode().iloc[0] if len(x.mode()) > 0 else np.nan),
        count=("RADAR", "count"),
    )
    summary = summary.join(gauge["RRE150Z0"].rename("target"))
    return summary


def plot_group_aggregated_correlations(summary, output_dir):
    stats = summary.corr(method="spearman")
    fig, ax = plt.subplots(figsize=(12, 10))
    sns.heatmap(stats, annot=True, fmt=".2f", cmap="coolwarm", ax=ax, center=0)
    ax.set_title("Spearman Correlation Matrix for Group Aggregates")
    save_figure(fig, output_dir, "group_aggregated_correlation.png")

    print("Top correlations with target:")
    target_corr = stats["target"].drop("target").abs().sort_values(ascending=False)
    print(target_corr)


def plot_target_vs_feature(summary, output_dir, sample_size=3000):
    numeric_cols = [
        "HEIGHT_mean",
        "HEIGHT_max",
        "ZH_mean_mean",
        "ZV_mean_mean",
        "KDP_mean_mean",
        "RHOHV_mean_mean",
        "AH_mean",
        "VISIB_mean_mean",
        "SW_mean_mean",
        "count",
    ]
    sample = summary.sample(min(len(summary), sample_size), random_state=42)
    for col in numeric_cols:
        fig, ax = plt.subplots(figsize=(8, 6))
        sns.scatterplot(data=sample, x=col, y="target", alpha=0.4, ax=ax)
        ax.set_title(f"Target vs. {col}")
        ax.set_xlabel(col)
        ax.set_ylabel("RRE150Z0")
        save_figure(fig, output_dir, f"target_vs_{col}.png")


def plot_profile_sample(radar, vertgroups, output_dir, sample_size=5):
    unique_groups = np.unique(vertgroups)
    chosen = np.random.choice(unique_groups, size=min(sample_size, len(unique_groups)), replace=False)
    sample = radar.copy()
    sample["vertgroup"] = vertgroups
    sample = sample[sample["vertgroup"].isin(chosen)]

    fig, ax = plt.subplots(figsize=(8, 6))
    for group_id, group_df in sample.groupby("vertgroup"):
        group_df = group_df.sort_values("HEIGHT", ascending=False)
        ax.plot(group_df["ZH_mean"].values, group_df["HEIGHT"].values, marker="o", label=f"group {group_id}")

    ax.set_xlabel("ZH_mean")
    ax.set_ylabel("HEIGHT")
    ax.set_title("Example Vertical Profiles for ZH_mean")
    ax.legend(frameon=False)
    save_figure(fig, output_dir, "sample_vertical_profiles_zH_mean.png")


