    parser = argparse.ArgumentParser(description="Explore QC radar dataset with diagnostic plots.")
    parser.add_argument("--input-dir", default=DEFAULT_QC_INPUT_DIR, help="Path to QC dataset directory")
    parser.add_argument("--output-dir", default="./qc_dataset_plots", help="Directory to save inspection plots")
    parser.add_argument("--sample-size", type=int, default=3000, help="Max samples for scatter plots")
    args = parser.parse_args()

    print("Loading QC dataset from:", args.input_dir)
    radar, gauge, vertgroups = load_qc_dataset(args.input_dir)
    print("Radar shape:", radar.shape)
    print("Gauge shape:", gauge.shape)
    print("Number of vertical groups:", len(np.unique(vertgroups)))

    # plot_gauge_distribution(gauge, args.output_dir)
    plot_gauge_timeline(gauge, args.output_dir)
    # plot_radar_category_distribution(radar, args.output_dir)
    plot_height_distribution(radar, args.output_dir)
    plot_sequence_length_distribution(vertgroups, args.output_dir)

